def _forced_stops(ctx: ToolContext, prices: dict[str, float]) -> set[str]:
    """Names whose mark is at or below the stop, measured from average cost."""
    stop_pct = float(ctx.settings.sizing_rules.get("stop_loss_pct", 0.20))
    forced: set[str] = set()
    for ticker, lot in ctx.portfolio.positions.items():
        price = prices.get(ticker, 0.0)
        if price <= 0 or lot.qty <= 0:
            continue
        average = lot.cost / lot.qty
        if average > 0 and price <= average * (1.0 - stop_pct):
            forced.add(ticker)
    return forced

